# p = P/(d-2), B_std = B/(d-2), q=d-4
# Omega = q O + P"'^3; P3 = tr P''^3; P2P = tr P''^2 tr P; P13=(tr P)''^3
coef={'"'P3':F(0),'P2P':F(0),'P13':F(0)}
def add(k,v): coef[k]+=v
# Q = (d-2) O = (d-2) box B - 2(d-2) W B -4 B P + 2 q bracket + q P"'^3
# X4 = 1/8 [ tr P tr((d-2)O)/16 - tr P tr P''^3/2 + tr P''^2 tr P''^2/8 - tr P''^4/4]
# In d=8, O is finite and supplied by problem; this routine checks only the P-sector in standard expansion if using Omega=Q/q and Q/q=O+P3/q.
# Let b=1/(d-2), q=d-4; standard P=(d-2)p, B=(d-2)Bstd.
# Given O_problem = (1/b)Q_without_qP3, Omega=O+q P''^3.
# Instead calculate standard GJMS8 flat-sector known formula in standard Schouten:
# 2''^8 4! Omega_std = Delta''^3 J - 8 div( ... ) + 4 Delta(P3) -12 Delta(J P2)+8 Delta(J''^3) -24 P4+48 J P3+24 P2''^2-48 J''^2 P2
# Expand tr Omega_std in d=8 and convert p=P/6.
# Variables standard invariants j=J, p2,p3,p4. At d=8.
# Formula inside brackets (ignoring total derivatives): 4 p3 -12 j p2 +8 j''^3 -24 p4 +48 j p3 +24 p2''^2 -48 j''^2 p2
# divide 2''^8*4!
inside={'"'p3':F(4),'jp2':F(-12),'j3':F(8),'p4':F(-24),'jp3':F(48),'p2sq':F(24),'j2p2':F(-48)}
# convert p=P/6, J=p1/2
conv={}
for k,v in inside.items():
    if k=='p3': kk='P3'; fac=F(1,6**3)
    elif k=='jp2': kk='P2P'; fac=F(1,2*6**2)
    elif k=='j3': kk='P13'; fac=F(1,2**3)
    elif k=='p4': kk='P4'; fac=F(1,6**4)
    elif k=='jp3': kk='P3P'; fac=F(1,2*6**3)
    elif k=='p2sq': kk='P2sq'; fac=F(1,6**4)
    elif k=='j2p2': kk='P2Psq'; fac=F(1,2**2*6**2)
    conv[kk]=conv.get(kk,F(0))+v*fac/F(2**8*24)
print(conv)
