from itertools import permutations
from math import comb

def d(p):
    n=len(p); seen=[False]*n; cycles=0
    for i in range(n):
        if not seen[i]:
            cycles += 1
            j=i
            while not seen[j]:
                seen[j]=True; j=p[j]
    return n-cycles

def mul(a,b):
    return tuple(a[b[i]] for i in range(len(a)))

def nc(g):
    # number of permutations u <= g in absolute order, by DP over cycle partitions
    n=len(g); m=d(g)
    count=0
    for u in permutations(range(n)):
        v=mul(u,g)  # u v = g
        if d(u)+d(v)==m:
            count += 1
    return count

for n in range(1,7):
    g=tuple((i+1)%n for i in range(n))
    got=nc(g)
    want=comb(2*n,n)//(n+1)
    print(n, got, want, got==want)
