from itertools import permutations
from math import comb

def d(p):
    n=len(p); seen=[False]*n; cycles=0
    for i in range(n):
        if not seen[i]:
            cycles += 1
            j=i
            while not seen[j]:
                seen[j]=True; j=p[j]
    return n-cycles

def mul(a,b): return tuple(a[b[i]] for i in range(len(a)))
def inv(a):
    out=[0]*len(a)
    for i,x in enumerate(a): out[x]=i
    return tuple(out)

def nc(g):
    out=[]
    for u in permutations(range(len(g))):
        v=mul(inv(u),g)
        if d(u)+d(v)==d(g): out.append(u)
    return out

def leq(u,v):
    w=mul(inv(u),v)
    return d(u)+d(w)==d(v)

for n in range(1,6):
    g=tuple((i+1)%n for i in range(n))
    elems=nc(g)
    count=0
    for u in elems:
        for v in elems:
            if leq(u*0 if False else u, v): count += 1
    want=comb(3*n,n)//(2*n+1)
    print(n, count, want, count==want)
