   rec=(typ,a,b,cell(x,y)); bonds.append(rec); adj[a].append((b,rec)); adj[b].append((a,rec))
def canon(p):
 ro=[]
 for q in [p,list(reversed(p))]:
  for k in range(6): ro.append(tuple(q[k:]+q[:k]))
 return min(ro)
