import numpy as np
from scipy.sparse.linalg import LinearOperator,eigsh
L1,L2=3,2; Nc=6; N=12; D=1<<N
cell=lambda x,y:(x%L1)+L1*(y%L2)
A=lambda x,y:cell(x,y); B=lambda x,y:Nc+cell(x,y)
bonds=[]
for x in range(L1):
 for y in range(L2):
  bonds += [('z',A(x,y),B(x,y)),('x',A(x,y),B(x-1,y)),('y',A(x,y),B(x+1,y-1))]
states=np.arange(D,dtype=np.int64); diag=np.zeros(D); flips=[]; coef=[]
for typ,i,j in bonds:
 bi=(states>>i)&1; bj=(states>>j)&1
 if typ=='z': diag += -np.where(bi==bj,1.,-1.)
 else:
  flips.append(states"'^((1<<i)|(1<<j))); coef.append(-np.ones(D) if typ=='"'x' else -np.where(bi==bj,1.,-1.))
def mv(v):
 out=diag*v
 for t,c in zip(flips,coef): out += c*v[t]
 return out
vals,vecs=eigsh(LinearOperator((D,D),matvec=mv),k=40,which='SA',tol=1e-11,maxiter=100000)
o=np.argsort(vals); vals=vals[o]; vecs=vecs[:,o]
print(vals)
for tol in [1e-8,1e-6,1e-4]:
 groups=[]
 for v in vals:
  if not groups or abs(v-groups[-1][-1])>tol: groups.append([v])
  else: groups[-1].append(v)
 print(tol,[(g[0],len(g)) for g in groups])
