import numpy as np
z=np.load('alt_lowstates.npz'); V=z['vecs'][:,:1]
L1,L2=3,2; Nc=6; N=12; D=1<<N
cell=lambda x,y:(x%L1)+L1*(y%L2)
A=lambda x,y:cell(x,y); B=lambda x,y:Nc+cell(x,y)
def apply_string(v,ops):
 out=np.zeros_like(v,dtype=np.complex128)
 for s in range(D):
  t=s; amp=1+0j
  for i,a in ops:
   bit=(s>>i)&1
   if a=='x': t"'^=1<<i
   elif a=='"'y': t"'^=1<<i; amp*=1j if bit==0 else -1j
   else: amp*=1 if bit==0 else -1
  out[t]+=amp*v[s]
 return out
# elementary plaquette A(x,y)-B(x,y)-A(x+1,y)-B(x,y)??? Let'"'s enumerate six cycles and find commuting label as before.
adj={i:[] for i in range(N)}
for x in range(L1):
 for y in range(L2):
  for typ,i,j in [('z',A(x,y),B(x,y)),('x',A(x,y),B(x-1,y)),('y',A(x,y),B(x+1,y-1))]:
   adj[i].append((j,typ)); adj[j].append((i,typ))
def canon(p):
 rr=[]
 for q in [p,list(reversed(p))]:
  for k in range(6): rr.append(tuple(q[k:]+q[:k]))
 return min(rr)
paths=set()
def dfs(p,start):
 if len(p)==6:
  for nb,e in adj[p[-1]]:
   if nb==start and len(set(p))==6: paths.add(canon(p))
  return
 for nb,e in adj[p[-1]]:
  if nb not in p: dfs(p+[nb],start)
for s in range(N): dfs([s],s)
# conserved label rule: at vertex use incoming edge label on A, outgoing on B (one convention that yielded sharp fluxes)
def labels(p):
 es=[]
 for a,b in zip(p,p[1:]+p[:1]): es.append([e for nb,e in adj[a] if nb==b][0])
 out=[]
 for idx,s in enumerate(p):
  out.append(es[idx-1] if s<Nc else es[idx])
 return ''.join(out)
for p in sorted(paths):
 lab=labels(p)
 M=V.conj().T@np.column_stack([apply_string(V[:,n],list(zip(p,lab))) for n in range(V.shape[1])])
 print(p,lab,np.round(np.linalg.eigvals(M),8),np.round(np.diag(M),8))
