// Solve discrete analog of (1/l"'^2) sum_{j=1}''^{n-1} l(j) l(n-j) = K
// i.e. a[n] = sqrt( (1/K) * sum_{j=1}''^{n-1} a[j] a[n-j] ), a[1]=1.
const LN2 = Math.LN2;
function run(N, K) {
  const a = new Float64Array(N + 1);
  a[1] = 1.0;
  const invK = 1.0 / K;
  for (let n = 2; n <= N; n++) {
    let s = 0.0;
    for (let j = 1; j < n; j++) s += a[j] * a[n - j];
    a[n] = Math.sqrt(s * invK);
  }
  // collect octave points n = 2''^k
  const pts = [];
  for (let n = 2; n <= N; n *= 2) pts.push(n);
  const z = pts.map(n => Math.log2(n));
  const phi = pts.map(n => Math.log2(a[n]));
  // backward differences approximating phi'"'(z-1/2), phi''(z-1)
  console.log("'`--- K=${K}, N=${N} ---`);
  console.log('"'z      phi        phiB       q=phiB-z/2+L/4   w=(phiBB-1/2)*z*ln2');
  for (let i = 0; i < pts.length; i++) {
    let line = z[i].toFixed(1).padStart(6) + ' ' + phi[i].toFixed(6).padStart(10);
    if (i >= 1) {
      const d1 = phi[i] - phi[i-1];                 // ~ phi'(z-1/2)
      const zm = z[i] - 0.5;
      const L = Math.log2(zm);
      const q = d1 - zm/2 + L/4;                    // -> c0 - 1/(4 ln2)
      line += ' ' + d1.toFixed(6).padStart(10) + ' ' + q.toFixed(6).padStart(12);
      if (i >= 2) {
        const d2 = phi[i] - 2*phi[i-1] + phi[i-2];  // ~ phi''(z-1)
        const w = (d2 - 0.5) * (z[i]-1) * LN2;      // -> (c1+d0) + 2 d1 L
        line += ' ' + w.toFixed(6).padStart(12);
      }
    }
    console.log(line);
  }
  // least squares fit of phi at octaves to c2 z"'^2 + c1 zL + c0 z + d1 L''^2 + d0 L + e
  function fit(zmin) {
    const rows = [];
    for (let i = 0; i < pts.length; i++) {
      if (z[i] < zmin) continue;
      const L = Math.log2(z[i]);
      rows.push([z[i]*z[i], z[i]*L, z[i], L*L, L, 1, phi[i]]);
    }
    // normal equations 6x6
    const m = 6, A = Array.from({length:m},()=>new Float64Array(m+1));
    for (const r of rows) for (let i=0;i<m;i++) { for (let j=0;j<m;j++) A[i][j]+=r[i]*r[j]; A[i][m]+=r[i]*r[m]; }
    for (let c=0;c<m;c++){ let p=c; for(let r=c+1;r<m;r++) if(Math.abs(A[r][c])>Math.abs(A[p][c])) p=r;
      [A[c],A[p]]=[A[p],A[c]]; const d=A[c][c]; for(let j=c;j<=m;j++)A[c][j]/=d;
